	private static boolean supports(FileFormat format, Collection<? extends RioSetting<?>> supportedSettings) {
		if (format instanceof TupleQueryResultFormat) {
			if (TupleQueryResultFormat.JSON.equals(format) || isNewlineDelimitedJson(format)) {
				return true;
			}
			return TupleQueryResultFormat.SPARQL.equals(format) && supportsXmlDeclarationSetting(supportedSettings);
		}
		if (format instanceof BooleanQueryResultFormat) {
			if (BooleanQueryResultFormat.JSON.equals(format)) {
				return true;
			}
			return BooleanQueryResultFormat.SPARQL.equals(format) && supportsXmlDeclarationSetting(supportedSettings);
		}
		if (!(format instanceof RDFFormat)) {
			return false;
		}

		if (RDFFormat.RDFXML.equals(format) || RDFFormat.TRIX.equals(format)) {
			return supportsXmlDeclarationSetting(supportedSettings);
		}
		return RDFFormat.JSONLD.equals(format)
				|| RDFFormat.NDJSONLD.equals(format)
				|| RDFFormat.RDFJSON.equals(format)
				|| RDFFormat.TURTLE.equals(format)
				|| RDFFormat.N3.equals(format)
				|| RDFFormat.TRIG.equals(format)
				|| RDFFormat.NTRIPLES.equals(format)
				|| RDFFormat.NQUADS.equals(format);
	}

	private static boolean isNewlineDelimitedJson(FileFormat format) {
		String mimeType = format.getDefaultMIMEType();
		return mimeType != null && mimeType.toLowerCase(Locale.ROOT).endsWith("ndjson");
	}

	private static boolean supportsXmlDeclarationSetting(Collection<? extends RioSetting<?>> supportedSettings) {
		return supportedSettings.contains(XMLWriterSettings.INCLUDE_XML_PI);
	}

	private static boolean usesXmlDeclaration(FileFormat format) {
		return TupleQueryResultFormat.SPARQL.equals(format)
				|| BooleanQueryResultFormat.SPARQL.equals(format)
				|| RDFFormat.RDFXML.equals(format)
				|| RDFFormat.TRIX.equals(format);
	}

